<?php section('projetos', 'Projetos demonstrativos', '04 / projects/'); ?>
<div class="project-toolbar"><p>Conceitos criados para demonstrar estrutura e possibilidades.</p><label class="project-search"><span>⌕</span><input type="search" placeholder="Buscar projetos..." aria-label="Buscar projetos" data-project-search></label></div>
<div class="filter-row"><div class="filter-chips" data-project-filters><button class="filter-chip active" type="button" data-filter="todos">Todos</button><?php $categories=[]; foreach ($portfolio['projects'] as $project) foreach ($project['technologies'] as $tech) $categories[$tech]=true; foreach (array_keys($categories) as $category): ?><button class="filter-chip" type="button" data-filter="<?= e($category) ?>"><?= e($category) ?></button><?php endforeach; ?></div><div class="view-toggle"><button class="active" type="button" data-project-view="cards" aria-label="Visualização em cards">▦</button><button type="button" data-project-view="list" aria-label="Visualização em lista">☰</button></div></div>
